import{_ as a,o as l,c as i,Q as e}from"./chunks/framework.b2e9bf53.js";const _=JSON.parse('{"title":"需求","description":"","frontmatter":{},"headers":[],"relativePath":"专题/后台管理系统常见需求/ruoyi项目单个接口超时设置.md","filePath":"专题/后台管理系统常见需求/ruoyi项目单个接口超时设置.md","lastUpdated":null}'),r={name:"专题/后台管理系统常见需求/ruoyi项目单个接口超时设置.md"},t=e('<h1 id="需求" tabindex="-1">需求 <a class="header-anchor" href="#需求" aria-label="Permalink to &quot;需求&quot;">​</a></h1><h2 id="用户与权限管理" tabindex="-1">用户与权限管理 <a class="header-anchor" href="#用户与权限管理" aria-label="Permalink to &quot;用户与权限管理&quot;">​</a></h2><ul><li>用户登录/退出（支持 Token）</li><li>权限控制（基于角色/路由/按钮权限）</li><li>登录日志、操作日志记录（可选）系统登录日志记录查询包含登录异常。</li></ul><h2 id="菜单与路由" tabindex="-1">菜单与路由 <a class="header-anchor" href="#菜单与路由" aria-label="Permalink to &quot;菜单与路由&quot;">​</a></h2><ul><li>动态菜单生成（根据权限返回）</li><li>路由懒加载</li></ul><h2 id="系统管理模块" tabindex="-1">系统管理模块 <a class="header-anchor" href="#系统管理模块" aria-label="Permalink to &quot;系统管理模块&quot;">​</a></h2><ul><li>菜单管理</li><li>角色管理，角色菜单权限分配、设置角色按机构进行数据范围权限划分。</li><li>用户管理，用户是系统操作者，该功能主要完成系统用户配置。</li><li>字典管理（如状态/性别/岗位等）对系统中经常使用的一些较为固定的数据进行维护。</li><li>参数配置（系统配置项，如分页大小）对系统动态配置常用参数。</li></ul><h2 id="数据展示模块-仪表盘" tabindex="-1">数据展示模块（仪表盘） <a class="header-anchor" href="#数据展示模块-仪表盘" aria-label="Permalink to &quot;数据展示模块（仪表盘）&quot;">​</a></h2><ul><li>首页代办、消息、图表、功能区</li><li>在线用户：当前系统中活跃用户状态、访问量监控。</li></ul><h2 id="系统设置" tabindex="-1">系统设置 <a class="header-anchor" href="#系统设置" aria-label="Permalink to &quot;系统设置&quot;">​</a></h2><ul><li>主题换肤</li><li>国际化切换（i18n）</li><li>多语言支持</li><li>个人设置（头像、密码修改等）</li></ul><h2 id="安全相关" tabindex="-1">安全相关 <a class="header-anchor" href="#安全相关" aria-label="Permalink to &quot;安全相关&quot;">​</a></h2><ul><li>路由守卫（Navigation Guard）</li><li>Token自动刷新（可选）</li><li>CSRF/XSS 处理（部分靠后端）</li></ul><h2 id="_8通用功能" tabindex="-1">8通用功能 <a class="header-anchor" href="#_8通用功能" aria-label="Permalink to &quot;8通用功能&quot;">​</a></h2><ul><li>分页、表格、表单、文件上传、Excel导入/导出</li><li>富文本编辑器（如Quill或WangEditor）</li></ul><h2 id="消息与通知" tabindex="-1">消息与通知 <a class="header-anchor" href="#消息与通知" aria-label="Permalink to &quot;消息与通知&quot;">​</a></h2><ul><li>消息通知列表（如系统通知）</li><li>即时消息推送（WebSocket / SSE）</li></ul><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h2><ul><li>在线构建器：拖动表单元素生成相应的HTML代码。</li><li>完全响应式布局（支持电脑、平板、手机等所有主流设备）</li><li>对常用js插件进行二次封装</li></ul><h1 id="插件与技术选型" tabindex="-1">插件与技术选型 <a class="header-anchor" href="#插件与技术选型" aria-label="Permalink to &quot;插件与技术选型&quot;">​</a></h1><h2 id="状态管理" tabindex="-1">状态管理 <a class="header-anchor" href="#状态管理" aria-label="Permalink to &quot;状态管理&quot;">​</a></h2><h2 id="路由" tabindex="-1">路由 <a class="header-anchor" href="#路由" aria-label="Permalink to &quot;路由&quot;">​</a></h2><ul><li>vue-router</li></ul><h2 id="ui组件库" tabindex="-1">UI组件库 <a class="header-anchor" href="#ui组件库" aria-label="Permalink to &quot;UI组件库&quot;">​</a></h2><ul><li>Element</li><li>Ant-Design</li></ul><h2 id="http请求库" tabindex="-1">HTTP请求库 <a class="header-anchor" href="#http请求库" aria-label="Permalink to &quot;HTTP请求库&quot;">​</a></h2><ul><li>Axios</li></ul><h2 id="图表展示" tabindex="-1">图表展示 <a class="header-anchor" href="#图表展示" aria-label="Permalink to &quot;图表展示&quot;">​</a></h2><ul><li>Echarts</li></ul><h2 id="富文本" tabindex="-1">富文本 <a class="header-anchor" href="#富文本" aria-label="Permalink to &quot;富文本&quot;">​</a></h2><ul><li>quill</li><li>vue-quill-editor</li></ul><h2 id="模拟后台数据" tabindex="-1">模拟后台数据 <a class="header-anchor" href="#模拟后台数据" aria-label="Permalink to &quot;模拟后台数据&quot;">​</a></h2><ul><li>mockjs</li></ul><h2 id="国际化" tabindex="-1">国际化 <a class="header-anchor" href="#国际化" aria-label="Permalink to &quot;国际化&quot;">​</a></h2><ul><li>vue-i18n</li></ul><h2 id="代码规范" tabindex="-1">代码规范 <a class="header-anchor" href="#代码规范" aria-label="Permalink to &quot;代码规范&quot;">​</a></h2><ul><li>eslint</li></ul><h2 id="辅助插件" tabindex="-1">辅助插件 <a class="header-anchor" href="#辅助插件" aria-label="Permalink to &quot;辅助插件&quot;">​</a></h2><ul><li>dayjs 日期处理库</li><li>moment</li></ul>',39),o=[t];function h(u,n,d,s,c,q){return l(),i("div",null,o)}const m=a(r,[["render",h]]);export{_ as __pageData,m as default};
